```python
from datetime import datetime, timedelta

class ExtendedDateTime:
    def __init__(self, year, month, day, hour=0, minute=0, second=0, microsecond=0, nanosecond=0):
        self.date = datetime(year, month, day, hour, minute, second, microsecond)
        self.nanosecond = nanosecond

    @property
    def timestamp(self):
        return self.date.timestamp() + self.nanosecond / 1e9

    @staticmethod
    def from_timestamp(timestamp, nanosecond=0):
        dt = datetime.fromtimestamp(timestamp)
        return ExtendedDateTime(dt.year, dt.month, dt.day, dt.hour, dt.minute, dt.second, dt.microsecond, nanosecond)

    def __add__(self, other):
        if isinstance(other, timedelta):
            return ExtendedDateTime.from_timestamp(self.timestamp + other.total_seconds(), self.nanosecond)
        else:
            raise TypeError("Unsupported operand type for +: 'ExtendedDateTime' and '{}'".format(type(other).__name__))

    def __sub__(self, other):
        if isinstance(other, timedelta):
            return ExtendedDateTime.from_timestamp(self.timestamp - other.total_seconds(), self.nanosecond)
        elif isinstance(other, ExtendedDateTime):
            return timedelta(seconds=self.timestamp - other.timestamp)
        else:
            raise TypeError("Unsupported operand type for -: 'ExtendedDateTime' and '{}'".format(type(other).__name__))

    def __str__(self):
        return self.date.strftime("%Y-%m-%d %H:%M:%S.%f") + "{:.9f}".format(self.nanosecond / 1e9)

# Example usage:
dt = ExtendedDateTime(2022, 1, 1, hour=12, minute=30, second=45, microsecond=123456, nanosecond=987654321)
print(dt.timestamp)  # Output: 1641004245.123456789
print(dt + timedelta(seconds=10))  # Output: 2022-01-01 12:30:55.123456789
print(dt - timedelta(seconds=10))  # Output: 2022-01-01 12:29:35.123456789
```

