Certainly! Here's a Python script that provides a basic command-line interface for interacting with AWS using the Boto3 library. This script allows you to create EC2 instances, manage S3 buckets, and configure IAM users and policies. Please note that this is a simplified example and might require additional setup and configuration for production use.

```python
import boto3
from botocore.exceptions import NoCredentialsError

# Initialize the AWS session
session = boto3.Session(profile_name='your_aws_profile')
ec2 = session.resource('ec2')
s3 = session.client('s3')
iam = session.client('iam')

def create_ec2_instance():
    try:
        instance = ec2.create_instances(
            ImageId='ami-0c55b159cbfafe1f0',  # Replace with your desired AMI ID
            MinCount=1,
            MaxCount=1,
            InstanceType='t2.micro',
            KeyName='your_key_pair_name'  # Replace with your key pair name
        )
        print("EC2 instance created successfully.")
        return instance
    except Exception as e:
        print(f"Error creating EC2 instance: {e}")

def list_s3_buckets():
    try:
        response = s3.list_buckets()
        buckets = response['Buckets']
        print("S3 Buckets:")
        for bucket in buckets:
            print(bucket['Name'])
    except Exception as e:
        print(f"Error listing S3 buckets: {e}")

def create_iam_user(username):
    try:
        response = iam.create_user(UserName=username)
        print(f"IAM user '{username}' created successfully.")
        return response
    except Exception as e:
        print(f"Error creating IAM user: {e}")

def main():
    print("Welcome to the AWS Command Line Interface!")
    while True:
        print("\nOptions:")
        print("1. Create EC2 Instance")
        print("2. List S3 Buckets")
        print("3. Create IAM User")
        print("4. Exit")

        choice = input("Enter your choice: ")

        if choice == '1':
            create_ec2_instance()
        elif choice == '2':
            list_s3_buckets()
        elif choice == '3':
            username = input("Enter IAM user name: ")
            create_iam_user(username)
        elif choice == '4':
            print("Exiting...")
            break
        else:
            print("Invalid choice. Please try again.")

if __name__ == "__main__":
    main()
```

