class ImageProcessor:
    def __init__(self, image_path):
        self.image = Image.open(image_path)

    def resize_image(self, new_width, new_height):
        self.image = self.image.resize((new_width, new_height))

    def save_image(self, output_path, format='PNG'):
        self.image.save(output_path, format)

    def rotate_image(self, angle):
        self.image = self.image.rotate(angle)

    def flip_image(self, direction='horizontal'):
        if direction == 'horizontal':
            self.image = self.image.transpose(Image.FLIP_LEFT_RIGHT)
        elif direction == 'vertical':
            self.image = self.image.transpose(Image.FLIP_TOP_BOTTOM)

    def convert_to_grayscale(self):
        self.image = self.image.convert('L')

# Example usage
if __name__ == "__main__":
    processor = ImageProcessor('input_image.jpg')
    processor.resize_image(800, 600)
    processor.rotate_image(45)
    processor.flip_image('vertical')
    processor.convert_to_grayscale()
    processor.save_image('output_image.jpg')
```

This script defines a class `ImageProcessor` that takes an image file path in its constructor. It provides methods to resize, rotate, flip, convert to grayscale, and save the modified image. You can use this library to perform various image processing tasks in your Python projects.

You can save this script in a file named `image_processor.py` and run it from the command line to see the example usage. Make sure to have the Pillow library installed (`pip install pillow`) before running the script.

Here's an example of how you could implement a plugin system in Python using a dictionary to register and call plugins, and a hook system using a list of functions to execute callbacks in a specific order:

Python 코드:

import importlib

class PluginSystem:
    def __init__(self):
        self.plugins = {}
        self.hooks = []

    def register_plugin(self, name, plugin):
        self.plugins[name] = plugin

    def unregister_plugin(self, name):
        del self.plugins[name]

    def call_plugin(self, name, *args, **kwargs):
        if name in self.plugins:
            plugin = self.plugins[name]
            return plugin(*args, **kwargs)
        else:
            raise ValueError(f"Plugin '{name}' not found.")

    def register_hook(self, hook):
        self.hooks.append(hook)

    def unregister_hook(self, hook):
        self.hooks.remove(hook)

    def execute_hooks(self, *args, **kwargs):
        for hook in self.hooks:
            hook(*args, **kwargs)

    def load_plugins(self, plugin_paths):
        for path in plugin_paths:
            try:
                plugin = importlib.import_module(path)
                self.register_plugin(plugin.__name__, plugin)
            except Exception as e:
                print(f"Error loading plugin '{path}': {e}")

# Example usage:

# Define some plugins

def plugin1(arg1, arg2):
    print(f"Plugin1 called with args: {arg1}, {arg2}")

def plugin2(arg1, arg2):
    print(f"Plugin2 called with args: {arg1}, {arg2}")

# Create a plugin system

plugin_system = PluginSystem()

# Register the plugins

plugin_system.register_plugin("plugin1", plugin1)
plugin_system.register_plugin("plugin2", plugin2)

# Call a plugin

plugin_system.call_plugin("plugin1", "arg1", "arg2")

# Register some hooks

def hook1():
    print("Hook1 executed")

def hook2():
    print("Hook2 executed")

plugin_system.register_hook(hook1)
plugin_system.register_hook(hook2)

# Execute the hooks

plugin_system.execute_hooks("arg1", "arg2")

# Load some plugins

plugin_system.load_plugins(["plugin3", "plugin4"])

# Call a plugin

plugin_system.call_plugin("plugin3", "arg1", "arg2")

# Execute the hooks

plugin_system.execute_hooks("arg1", "arg2")

# Unregister a plugin

plugin_system.unregister_plugin("plugin1")

# Call the plugin again

plugin_system.call_plugin("plugin1", "arg1", "arg2")

# Unregister a hook

plugin_system.unregister_hook(hook1)

# Execute the hooks again

plugin_system.execute_hooks("arg1", "arg2")
