```python
from immutables import Map, List
from toolz import compose
from pyds import LinkedList

# Define a simple linked list class using Immutable collections
class PersistentLinkedList:
    def __init__(self, head=None):
        self.head = head

    @classmethod
    def from_list(cls, lst):
        return cls(List(lst))

    def append(self, value):
        new_head = Map({'value': value, 'next': self.head})
        return PersistentLinkedList(new_head)

    def __iter__(self):
        node = self.head
        while node:
            yield node['value']
            node = node['next']

# Create a persistent linked list from a list
persistent_list = PersistentLinkedList.from_list([1, 2, 3])

# Iterate over the persistent linked list
for value in persistent_list:
    print(value)

# Use toolz to compose functions for functional programming
def map_function(func, lst):
    return list(map(func, lst))

# Use PyDS to create a regular linked list
regular_list = LinkedList([1, 2, 3])

# Use toolz to compose functions for functional programming
def map_function(func, lst):
    return list(map(func, lst))

# Compose a function to square each element in the list
squared_list = compose(map_function, lambda x: x**2)([1, 2, 3])

print(squared_list)
```

This example demonstrates how to create a persistent, functional, and immutable data structure using `Immutable collections` and `toolz`. It also shows how to use `PyDS` to create a regular linked list and compose functions for functional programming. Please note that `PyDS` is not a standard library, so you would need to install it separately if you want to use it in your project.

