```python
import cssutils

def create_stylesheet(theme_name, colors, typography):
    stylesheet = cssutils.parseString("""
        :root {
            --background-color: #ffffff;
            --text-color: #000000;
            --accent-color: #0000ff;
        }
    """)

    # Update CSS variables with theme-specific values
    for variable, value in colors.items():
        stylesheet.cssRules[0].style.setProperty(variable, value)

    # Update typography properties
    for property, value in typography.items():
        stylesheet.cssRules[0].style.setProperty(property, value)

    return stylesheet

def generate_css(stylesheet):
    return stylesheet.cssText

# Example usage
