```python
import hashlib
from Crypto.Cipher import AES
from Crypto.PublicKey import RSA
from Crypto.Signature import pkcs1_15
from Crypto.Hash import SHA256
from Crypto.Random import get_random_bytes

class CryptographicLibrary:
    def __init__(self):
        self.key = None
        self.public_key = None
        self.private_key = None

    def generate_key(self, key_size):
        self.key = get_random_bytes(key_size)

    def generate_rsa_keypair(self, key_size):
        self.private_key = RSA.generate(key_size)
        self.public_key = self.private_key.publickey()

    def encrypt_aes(self, plaintext, key):
        cipher = AES.new(key, AES.MODE_EAX)
        ciphertext, tag = cipher.encrypt_and_digest(plaintext)
        return ciphertext, tag, cipher.nonce

    def decrypt_aes(self, ciphertext, tag, nonce, key):
        cipher = AES.new(key, AES.MODE_EAX, nonce=nonce)
        plaintext = cipher.decrypt_and_verify(ciphertext, tag)
        return plaintext

    def sign_data(self, data, private_key):
        hash_object = SHA256.new(data)
        signer = pkcs1_15.new(private_key)
        signature = signer.sign(hash_object)
        return signature

    def verify_signature(self, data, signature, public_key):
        hash_object = SHA256.new(data)
        verifier = pkcs1_15.new(public_key)
        try:
            verifier.verify(hash_object, signature)
            return True
        except (ValueError, TypeError):
            return False

    def hash_data(self, data):
        return hashlib.sha256(data).hexdigest()

    def generate_mac(self, data, key):
        mac = hmac.new(key, data, hashlib.sha256)
        return mac.digest()

    def verify_mac(self, data, mac, key):
        expected_mac = self.generate_mac(data, key)
        return hmac.compare_digest(mac, expected_mac)
```

