Certainly! To parse a query string using a nested dictionary structure in Python, you can use the `urllib.parse` module to parse the query string into a dictionary, and then recursively create the nested dictionary structure. Here's an example code snippet:

```python
from urllib.parse import parse_qs, urlparse

def parse_query_string(query_string):
    query_dict = parse_qs(query_string)
    return create_nested_dict(query_dict)

def create_nested_dict(query_dict):
    nested_dict = {}
    for key, value in query_dict.items():
        keys = key.split('.')
        current_dict = nested_dict
        for k in keys[:-1]:
            if k not in current_dict:
                current_dict[k] = {}
            current_dict = current_dict[k]
        current_dict[keys[-1]] = value[0]  # Assuming there's only one value for each key
    return nested_dict

# Example usage
query_string = "name=John&address.city=New York&address.country=USA&interests.0=Sports&interests.1=Reading"
nested_dict = parse_query_string(query_string)
print(nested_dict)
```

