Certainly! Here's a Python script that demonstrates how to import the necessary libraries, establish an Amazon Athena connection using your AWS credentials, execute a SQL query, and retrieve the results:

```python
import boto3
from botocore.exceptions import NoCredentialsError
from pyathena import connect

def create_athena_connection(access_key_id, secret_access_key, region_name):
    try:
        athena_client = boto3.client(
            'athena',
            aws_access_key_id=access_key_id,
            aws_secret_access_key=secret_access_key,
            region_name=region_name
        )
        return athena_client
    except NoCredentialsError:
        print("AWS credentials not found. Please check your configuration.")

def execute_query(athena_client, database_name, query):
    try:
        response = athena_client.start_query_execution(
            QueryString=query,
            QueryExecutionContext={
                'Database': database_name
            },
            ResultConfiguration={
                'OutputLocation': 's3://your-bucket-name/'
            }
        )
        query_execution_id = response['QueryExecutionId']
        print(f"Query execution ID: {query_execution_id}")
        return query_execution_id
    except Exception as e:
        print(f"Error executing query: {e}")

def retrieve_results(athena_client, query_execution_id):
    try:
        while True:
            response = athena_client.get_query_results(
                QueryExecutionId=query_execution_id
            )
            results = response['ResultSet']['Rows']
            if not results:
                break
            for row in results:
                print(row['Data'])
        print("Query results retrieved successfully.")
    except Exception as e:
        print(f"Error retrieving results: {e}")

# Example usage
access_key_id = 'YOUR_ACCESS_KEY_ID'
secret_access_key = 'YOUR_SECRET_ACCESS_KEY'
region_name = 'YOUR_REGION_NAME'
database_name = 'YOUR_DATABASE_NAME'
query = 'SELECT * FROM your_table'

athena_client = create_athena_connection(access_key_id, secret_access_key, region_name)
if athena_client:
    query_execution_id = execute_query(athena_client, database_name, query)
    retrieve_results(athena_client, query_execution_id)
```

Make sure to replace `'YOUR_ACCESS_KEY_ID'`, `'YOUR_SECRET_ACCESS_KEY'`, `'YOUR_REGION_NAME'`, and `'YOUR_DATABASE_NAME'` with your actual AWS credentials and database details. Adjust the `query` variable to match the SQL query you want to execute. Additionally, make sure to replace `'s3://your-bucket-name/'` with the S3 bucket where Athena should store the query results.

This script demonstrates the basic steps to establish a connection, execute a query, and retrieve the results using the `pyathena` library. Note that the `boto3` library is used for interacting with AWS services, and the `pyathena` library is used for interacting with Amazon Athena.

