```python
import inspect
from functools import singledispatch

def singledispatch(func):
    registry = {}

    def wrapper(*args, **kwargs):
        sig = inspect.signature(func)
        bound_args = sig.bind(*args, **kwargs)
        bound_args.apply_defaults()

        for name, value in bound_args.arguments.items():
            if name in registry:
                return registry[name](value)

        return func(*args, **kwargs)

    wrapper.registry = registry
    wrapper.register = registry.__setitem__

    return wrapper

# Patch the built-in function len to use singledispatch
if hasattr(len, 'register'):
    len.register = len.registry.__setitem__
else:
    len.registry = {}
    len.register = len.registry.__setitem__

    def len_dispatch(obj):
        for name, func in len.registry.items():
            if name in inspect.getmro(type(obj)):
                return func(obj)

    len.__wrapped__ = len
    len.__wrapped__ = len_dispatch
```
