import pytz

# Shim for pytz.timezone
def timezone(tz_name):
    # Create a shim for the pytz.timezone function
    def shim(tz_name):
        return pytz.timezone(tz_name)
    return shim(tz_name)

# Shim for pytz.utc
def utc():
    # Create a shim for the pytz.utc function
    return pytz.utc

# Shim for pytz.timezone('UTC')
def utc_timezone():
    # Create a shim for the pytz.timezone('UTC') function
    return pytz.timezone('UTC')
```

