```python
import json
from pydantic import BaseModel
from typing import List

class JsonPatch(BaseModel):
    op: str
    path: str
    value: str = None
    from_: str = None

def apply_json_patch(json_doc: dict, patches: List[JsonPatch]) -> dict:
    for patch in patches:
        if patch.op == "add":
            path_parts = patch.path.split("/")
            current_obj = json_doc
            for part in path_parts[:-1]:
                if part not in current_obj:
                    current_obj[part] = {}
                current_obj = current_obj[part]
            current_obj[path_parts[-1]] = patch.value
        elif patch.op == "remove":
            path_parts = patch.path.split("/")
            current_obj = json_doc
            for part in path_parts[:-1]:
                if part not in current_obj:
                    raise ValueError(f"Path {patch.path} does not exist in the JSON document.")
                current_obj = current_obj[part]
            del current_obj[path_parts[-1]]
        elif patch.op == "replace":
            path_parts = patch.path.split("/")
            current_obj = json_doc
            for part in path_parts[:-1]:
                if part not in current_obj:
                    raise ValueError(f"Path {patch.path} does not exist in the JSON document.")
                current_obj = current_obj[part]
            current_obj[path_parts[-1]] = patch.value
        elif patch.op == "move":
            path_parts = patch.path.split("/")
            current_obj = json_doc
            for part in path_parts[:-1]:
                if part not in current_obj:
                    raise ValueError(f"Path {patch.path} does not exist in the JSON document.")
                current_obj = current_obj[part]
            moved_value = current_obj[path_parts[-1]]
            path_parts = patch.from_.split("/")
            current_obj = json_doc
            for part in path_parts[:-1]:
                if part not in current_obj:
                    raise ValueError(f"Path {patch.from_} does not exist in the JSON document.")
                current_obj = current_obj[part]
            current_obj[path_parts[-1]] = moved_value
            del current_obj[path_parts[-1]]
        elif patch.op == "copy":
            path_parts = patch.path.split("/")
            current_obj = json_doc
            for part in path_parts[:-1]:
                if part not in current_obj:
                    raise ValueError(f"Path {patch.path} does not exist in the JSON document.")
                current_obj = current_obj[part]
            copied_value = current_obj[patch.from_.split("/")[-1]]
            current_obj[path_parts[-1]] = copied_value
        else:
            raise ValueError(f"Unsupported operation: {patch.op}")

    return json_doc
