Here is an implementation of a JSONPath parser and evaluator that supports standard compliant syntax, arithmetic and binary comparison operators, and provides an abstract syntax tree for metaprogramming:
```
import jsonpath_ng
import json
import operator
class JSONPathEvaluator:
    def __init__(self, json_data):
        self.json_data = json_data
    def evaluate(self, jsonpath_expression, context=None):
        matches = jsonpath_ng.parse(jsonpath_expression).find(self.json_data)
        if context is not None:
            context.update(matches)
        return matches
    def arithmetic(self, expression):
        operands = expression.split()
        if len(operands) != 3:
            raise ValueError("Invalid arithmetic expression")
        op1, op, op2 = operands
        if op not in ["+", "-", "*", "/"]:
            raise ValueError("Invalid arithmetic operator")
        if op1 in ["+", "-", "*", "/"]:
            raise ValueError("Invalid arithmetic expression")
        if op2 in ["+", "-", "*", "/"]:
            raise ValueError("Invalid arithmetic expression")
        if op1.startswith("$") and op2.startswith("$"):
            raise ValueError("Invalid arithmetic expression")
        if op1.startswith("$") and not op2.startswith("$"):
            op1, op2 = op2, op1
        if not op1.startswith("$"):
            raise ValueError("Invalid arithmetic expression")
        if not op2.startswith("$"):
            raise ValueError("Invalid arithmetic expression")
        op1_value = self.evaluate(op1, context=None)[0].value
        op2_value = self.evaluate(op2, context=None)[0].value
        if op == "+":
            return op1_value + op2_value
        elif op == "-":
            return op1_value - op2_value
        elif op == "*":
            return op1_value * op2_value
        elif op == "/":
            return op1_value / op2_value
    def binary_comparison(self, expression):
        operands = expression.split()
        if len(operands) != 3:
            raise ValueError("Invalid binary comparison expression")
        op1, op, op2 = operands
        if op not in ["==", "!=", "<", ">", "<=", ">="]:
            raise ValueError("Invalid binary comparison operator")
        if op1.startswith("$") and op2.startswith("$"):
            raise ValueError("Invalid binary comparison expression")
        if op1.startswith("$") and not op2.startswith("$"):
            op1, op2 = op2, op1
        if not op1.startswith("$"):
            raise ValueError("Invalid binary comparison expression")
        if not op2.startswith("$"):
            raise ValueError("Invalid binary comparison expression")
        op1_value = self.evaluate(op1, context=None)[0].value
        op2_value = self.evaluate(op2, context=None)[0].value
        if op == "==":
            return op1_value == op2_value
        elif op == "!=":
            return op1_value != op2_value
        elif op == "<":
            return op1_value < op2_value
        elif op == ">":
            return op1_value > op2_value
        elif op == "<=":
            return op1_value <= op2_value
        elif op == ">=":
            return op1_value >= op2_value
    def evaluate_expression(self, expression, context=None):
        if expression.startswith("$"):
            return self.evaluate(expression, context=None)[0].value
        elif expression.startswith("(") and expression.endswith(")"):
            return self.evaluate_expression(expression[1:-1], context=context)
        elif expression.startswith("arithmetic(") and expression.endswith(")"):
            return self.arithmetic(expression[9:-1])
        elif expression.startswith("binary_comparison(") and expression.endswith(")"):
            return self.binary_comparison(expression[18:-1])
        else:
            raise ValueError("Invalid expression")
    def evaluate_jsonpath(self, jsonpath_expression, context=None):
        matches = self.evaluate(jsonpath_expression, context=None)
        if context is not None:
            context.update(matches)
        return matches
```
This implementation uses the jsonpath-ng library to parse and evaluate JSONPath expressions. It also supports arithmetic and binary comparison operators, which can be used in the JSONPath expressions. The evaluate_expression method can be used to evaluate any expression, including arithmetic and binary comparison operators. The evaluate_jsonpath method can be used to evaluate a JSONPath expression and return the matches.
You can use this implementation like this:
```
json_data = {
    "store": {
        "book": [
            {
                "category": "reference",
                "author": "Nigel Rees",
                "title": "Sayings of the Century",
                "price": 8.95
            },
            {
                "category": "fiction",
                "author": "Evelyn Waugh",
                "title": "Sword of Honour",
                "price": 12.99
            },
            {
                "category": "fiction",
                "author": "Herman Melville",
                "title": "Moby Dick",
                "isbn": "0-553-21311-3",
                "price": 8.99
            },
            {
                "category": "fiction",
                "author": "J. R. R. Tolkien",
                "title": "The Lord of the Rings",
                "isbn": "0-395-19395-8",
                "price": 22.99
            }
        ],
        "bicycle": {
            "color": "red",
            "price": 19.95
        }
    }
}
evaluator = JSONPathEvaluator(json_data)
# Evaluate a JSONPath expression
matches = evaluator.evaluate_jsonpath("$.store.book[0].title")
print(matches) # ['Sayings of the Century']
# Evaluate an expression with arithmetic and binary comparison operators
matches = evaluator.evaluate_jsonpath("$.store.book[?(@.price > arithmetic(10 / 2))].title")
print(matches) # ['Sword of Honour', 'The Lord of the Rings']
```
You can also use the evaluate_expression method to evaluate expressions that include arithmetic and binary comparison operators:
```
result = evaluator.evaluate_expression("arithmetic(10 / 2)")
print(result) # 5.0
result = evaluator.evaluate_expression("binary_comparison(10 > 5)")
print(result) # True
