Certainly! Below is an example of how you can use the Google Sheets API to read and write data to a spreadsheet, perform sheet management operations, and format cells and sheets. Please note that this example assumes you have already set up authentication for the Google Sheets API and have the necessary credentials.

```python
from google.oauth2.service_account import Credentials
from googleapiclient.discovery import build

# Replace with your own credentials file path
SCOPES = ['https://www.googleapis.com/auth/spreadsheets']
creds = Credentials.from_service_account_file('credentials.json', SCOPES)
service = build('sheets', 'v4', credentials=creds)

# Replace with your spreadsheet ID
spreadsheet_id = 'your_spreadsheet_id'

# Reading data from a specific cell
cell_range = 'Sheet1!A1'
result = service.spreadsheets().values().get(spreadsheetId=spreadsheet_id, range=cell_range).execute()
print(f"Cell value: {result.get('values', [])[0][0]}")

# Writing data to a specific cell
cell_range = 'Sheet1!B2'
value_input_option = 'USER_ENTERED'
values = [
    ['New Value']
]
body = {
    'values': values
}
result = service.spreadsheets().values().update(spreadsheetId=spreadsheet_id, range=cell_range, valueInputOption=value_input_option, body=body).execute()
print(f"Updated cell value: {result.get('updatedData', [])[0][0]}")

# Adding a new sheet
new_sheet_title = 'New Sheet'
add_sheet_request_body = {
    'requests': [
        {
            'addSheet': {
                'properties': {
                    'title': new_sheet_title
                }
            }
        }
    ]
}
service.spreadsheets().batchUpdate(spreadsheetId=spreadsheet_id, body=add_sheet_request_body).execute()

# Removing an existing sheet
remove_sheet_request_body = {
    'requests': [
        {
            'deleteSheet': {
                'sheetId': your_sheet_id  # Replace with the ID of the sheet to remove
            }
        }
    ]
}
service.spreadsheets().batchUpdate(spreadsheetId=spreadsheet_id, body=remove_sheet_request_body).execute()

# Renaming an existing sheet
rename_sheet_request_body = {
    'requests': [
        {
            'updateSheetProperties': {
                'properties': {
                    'sheetId': your_sheet_id,  # Replace with the ID of the sheet to rename
                    'title': 'New Sheet Title'
                },
                'fields': 'title'
            }
        }
    ]
}
service.spreadsheets().batchUpdate(spreadsheetId=spreadsheet_id, body=rename_sheet_request_body).execute()

# Formatting a cell
format_cell_request_body = {
    'requests': [
        {
            'updateCell': {
                'cell': {
                    'userEnteredFormat': {
                        'backgroundColor': {
                            'red': 0.5,
                            'green': 0.5,
                            'blue': 0.5
                        },
                        'horizontalAlignment': 'CENTER',
                        'verticalAlignment': 'MIDDLE'
                    }
                },
                'range': {
                    'sheetId': your_sheet_id,  # Replace with the ID of the sheet
                    'startRowIndex': 0,
                    'endRowIndex': 1,
                    'startColumnIndex': 0,
                    'endColumnIndex': 1
                },
                'fields': 'userEnteredFormat'
            }
        }
    ]
}
service.spreadsheets().batchUpdate(spreadsheetId=spreadsheet_id, body=format_cell_request_body).execute()

# Formatting a sheet
format_sheet_request_body = {
    'requests': [
        {
            'updateSheetProperties': {
                'properties': {
                    'sheetId': your_sheet_id,  # Replace with the ID of the sheet
                    'gridProperties': {
                        'rowCount': 100,
                        'columnCount': 100
                    }
                },
                'fields': 'gridProperties'
            }
        }
    ]
}
service.spreadsheets().batchUpdate(spreadsheetId=spreadsheet_id, body=format_sheet_request_body).execute()
```

Please replace `'your_spreadsheet_id'` with the actual ID of your Google Sheets spreadsheet and `your_sheet_id` with the ID of the sheet you want to remove or rename. Also, update the `new_sheet_title` and `format_cell_request_body` as needed for your specific requirements.

