    'location': location,
    'sku': {
        'name': storage_sku
    },
    'kind': 'StorageV2',
    'access_tier': 'Hot'
}
storage_account_result = resource_client.storage_accounts.create(resource_group_name, storage_account_name, storage_account_params)
print(f"Storage account '{storage_account_name}' created.")

# Define the virtual machine parameters
