    'location': location,
    'ip_configurations': [{
        'name': nic_name,
        'subnet': {
            'id': f'/subscriptions/{subscription_id}/resourceGroups/{resource_group_name}/providers/Microsoft.Network/virtualNetworks/{vnet_name}/subnets/{subnet_name}'
        }
    }]
}
nic_result = resource_client.network_interfaces.create_or_update(resource_group_name, nic_name, nic_params)
print(f"Network interface '{nic_name}' created.")

vm_params = {
    'location': location,
    'os_profile': {
        'computer_name': vm_name,
        'admin_username': admin_username,
        'admin_password': admin_password
    },
    'hardware_profile': {
        'vm_size': vm_size
    },
    'storage_profile': {
        'image_reference': {
            'publisher': 'Canonical',
            'offer': 'UbuntuServer',
            'sku': '18.04-LTS',
            'version': 'latest'
