        }
    },
    'network_profile': {
        'network_interfaces': [{
            'id': nic_result.id
        }]
    }
}
vm_result = compute_client.virtual_machines.create_or_update(resource_group_name, vm_name, vm_params)
print(f"Virtual machine '{vm_name}' created.")
