import requests
from requests.auth import HTTPBasicAuth

# Task 1: List all public repositories
def list_public_repositories():
    url = "https://api.github.com/repositories"
    response = requests.get(url)
    if response.status_code == 200:
        return response.json()
    else:
        return None

# Task 2: Create a new repository
def create_repository(name, description):
    url = "https://api.github.com/user/repos"
    headers = {'Accept': 'application/vnd.github.v3+json'}
    data = {"name": name, "description": description}
    response = requests.post(url, json=data, headers=headers)
    if response.status_code == 201:
        return response.json()
    else:
        return None

# Task 3: Add a collaborator to a repository
def add_collaborator(repo_id, username, role):
    url = f"https://api.github.com/repos/{repo_id}/collaborators/{username}"
    headers = {'Accept': 'application/vnd.github.v3+json'}
    data = {"role": role}
    response = requests.put(url, json=data, headers=headers)
    if response.status_code == 204:
        return True
    else:
        return False

# Task 4: Get a list of all issues for a repository
def get_issues_for_repository(repo_id):
    url = f"https://api.github.com/repos/{repo_id}/issues"
    response = requests.get(url)
    if response.status_code == 200:
        return response.json()
    else:
        return None

# Task 5: Create a new issue
def create_new_issue(repo_id, title, body):
    url = f"https://api.github.com/repos/{repo_id}/issues"
    headers = {'Accept': 'application/vnd.github.v3+json'}
    data = {"title": title, "body": body}
    response = requests.post(url, json=data, headers=headers)
    if response.status_code == 201:
        return response.json()
    else:
        return None

# Task 6: Get a list of all pull requests for a repository
def get_pull_requests_for_repository(repo_id):
    url = f"https://api.github.com/repos/{repo_id}/pulls"
    response = requests.get(url)
    if response.status_code == 200:
        return response.json()
    else:
        return None

# Example usage
if __name__ == "__main__":
    # Replace with your GitHub credentials
    username = "your_github_username"
    password = "your_github_password"

    # Task 1: List all public repositories
    public_repos = list_public_repositories()
    print("Public Repositories:")
    for repo in public_repos:
        print(f"{repo['name']} - {repo['description']}")

    # Task 2: Create a new repository
    new_repo_name = "my-new-repo"
    new_repo_desc = "My New Repo"
    created_repo = create_repository(new_repo_name, new_repo_desc)
    print(f"Created Repository: {created_repo['name']}")

    # Task 3: Add a collaborator to a repository
    repo_id = "your_repository_id"
    collaborator_username = "collaborator_user"
    role = "admin"
    success = add_collaborator(repo_id, collaborator_username, role)
    if success:
        print(f"Collaborator {collaborator_username} added to repository.")
    else:
        print("Failed to add collaborator.")

    # Task 4: Get a list of all issues for a repository
    issues = get_issues_for_repository(repo_id)
    print("\nIssues in Repository:")
    for issue in issues:
        print(f"{issue['title']} - {issue['state']}")

    # Task 5: Create a new issue
    issue_title = "New Issue"
    issue_body = "This is a new issue."
    new_issue = create_new_issue(repo_id, issue_title, issue_body)
    print(f"\nCreated Issue: {new_issue['title']}")

    # Task 6: Get a list of all pull requests for a repository
    pull_requests = get_pull_requests_for_repository(repo_id)
    print("\nPull Requests in Repository:")
    for pr in pull_requests:
        print(f"{pr['title']} - {pr['state']}")
