```python
import ast
from ast import *

def unparse(node):
    if isinstance(node, AST):
        return unparse(node)
    elif isinstance(node, (Constant, Name, Attribute)):
        return str(node.value)
    elif isinstance(node, BinOp):
        return f"{unparse(node.left)} {node.op.__name__} {unparse(node.right)}"
    elif isinstance(node, UnaryOp):
        return f"{node.op.__name__} {unparse(node.operand)}"
    elif isinstance(node, Call):
        return f"{unparse(node.func)}({', '.join(map(unparse, node.args))})"
    elif isinstance(node, (List, Tuple, Set)):
        return f"[{', '.join(map(unparse, node.elts))}]"
    elif isinstance(node, Dict):
        return f"{{'{', '".join(f"{unparse(k)}: {unparse(v)}" for k, v in node.items())}}}"
    elif isinstance(node, (If, While)):
        return f"{node.__class__.__name__}({unparse(node.test)}, {unparse(node.body)}, {unparse(node.orelse)})"
    elif isinstance(node, (For, With)):
        return f"{node.__class__.__name__}({unparse(node.target)}, {unparse(node.iter)}, {unparse(node.body)}, {unparse(node.orelse)})"
    elif isinstance(node, (Try, ExceptHandler)):
        return f"{node.__class__.__name__}({unparse(node.body)}, {unparse(node.handlers)}, {unparse(node.orelse)}, {unparse(node.finalbody)})"
    elif isinstance(node, (Import, ImportFrom)):
        return f"{node.__class__.__name__}({', '.join(node.names)})"
    elif isinstance(node, (Assign, AugAssign)):
        return f"{unparse(node.target)} = {unparse(node.value)}"
    elif isinstance(node, (Return, Yield, YieldFrom)):
        return f"{node.__class__.__name__}({unparse(node.value)})"
    elif isinstance(node, (Delete, Raise)):
        return f"{node.__class__.__name__}({unparse(node.targets)})"
    elif isinstance(node, (Break, Continue)):
        return f"{node.__class__.__name__}"
    else:
        raise ValueError(f"Unsupported node type: {type(node)}")

# Example usage:
code = """
def add(x, y):
    return x + y
"""
tree = ast.parse(code)
print(unparse(tree))
```

This code defines a recursive function `unparse` that traverses an abstract syntax tree (AST) and converts it back into Python source code. The function supports various AST node types such as `Constant`, `Name`, `Attribute`, `BinOp`, `UnaryOp`, `Call`, `List`, `Tuple`, `Set`, `Dict`, `If`, `While`, `For`, `With`, `Try`, `ExceptHandler`, `Import`, `ImportFrom`, `Assign`, `AugAssign`, `Return`, `Yield`, `YieldFrom`, `Delete`, `Raise`, `Break`, and `Continue`.

Please note that this implementation is quite basic and may not cover all possible cases in the AST. You can extend it further by adding support for additional node types and their respective unparse logic.

