```python
import git
from gitdb import GitDB

class Mirror:
    def __init__(self, repository_path):
        self.repository = git.Repo(repository_path)
        self.gitdb = GitDB(repository_path)

    def clone_repository(self, remote_url):
        try:
            self.repository.clone(remote_url)
            print("Repository cloned successfully.")
        except Exception as e:
            print(f"Error cloning repository: {e}")

    def push_to_remote(self, remote_url):
        try:
            self.repository.remotes.origin.push()
            print("Pushed to remote successfully.")
        except Exception as e:
            print(f"Error pushing to remote: {e}")

    def pull_from_remote(self, remote_url):
        try:
            self.repository.remotes.origin.pull()
            print("Pulled from remote successfully.")
        except Exception as e:
            print(f"Error pulling from remote: {e}")

    def commit_changes(self, message):
        try:
            self.repository.git.add('.')
            self.repository.index.commit(message)
            print("Changes committed successfully.")
        except Exception as e:
            print(f"Error committing changes: {e}")

    def fetch_remote(self, remote_url):
        try:
            self.repository.remotes.origin.fetch()
            print("Fetched remote successfully.")
        except Exception as e:
            print(f"Error fetching remote: {e}")

# Example usage
mirror = Mirror('/path/to/repository')
mirror.clone_repository('https://github.com/your-repo.git')
mirror.push_to_remote('https://github.com/your-repo.git')
mirror.pull_from_remote('https://github.com/your-repo.git')
mirror.commit_changes('Initial commit')
mirror.fetch_remote('https://github.com/your-repo.git')
```

