```python
import argparse
from pywebhdfs.webhdfs import PyWebHdfsClient

def create_directory(hdfs_client, directory):
    try:
        hdfs_client.create_directory(directory)
        print(f"Directory {directory} created successfully.")
    except Exception as e:
        print(f"Error creating directory: {e}")

def delete_directory(hdfs_client, directory):
    try:
        hdfs_client.delete_directory(directory)
        print(f"Directory {directory} deleted successfully.")
    except Exception as e:
        print(f"Error deleting directory: {e}")

def create_file(hdfs_client, file_path, content):
    try:
        hdfs_client.create_file(file_path, content)
        print(f"File {file_path} created successfully.")
    except Exception as e:
        print(f"Error creating file: {e}")

def delete_file(hdfs_client, file_path):
    try:
        hdfs_client.delete_file(file_path)
        print(f"File {file_path} deleted successfully.")
    except Exception as e:
        print(f"Error deleting file: {e}")

def read_file(hdfs_client, file_path):
    try:
        content = hdfs_client.read_file(file_path)
        print(f"File {file_path} content:")
        print(content)
    except Exception as e:
        print(f"Error reading file: {e}")

def list_files(hdfs_client, directory):
    try:
        files = hdfs_client.list_files(directory)
        print(f"Files in {directory}:")
        for file in files:
            print(file)
    except Exception as e:
        print(f"Error listing files: {e}")

def display_metadata(hdfs_client, file_path):
    try:
        metadata = hdfs_client.get_file_status(file_path)
        print(f"Metadata for {file_path}:")
        print(metadata)
    except Exception as e:
        print(f"Error displaying metadata: {e}")

def main():
    parser = argparse.ArgumentParser(description='CLI for interacting with HDFS')
    parser.add_argument('command', choices=['create_directory', 'delete_directory', 'create_file', 'delete_file', 'read_file', 'list_files', 'display_metadata'])
    parser.add_argument('path', help='Path to the directory, file, or file content')
    parser.add_argument('content', nargs='?', help='Content of the file to create')

    args = parser.parse_args()

    hdfs_client = PyWebHdfsClient(host='your_hdfs_host', port='your_hdfs_port', user_name='your_hdfs_user')

    if args.command == 'create_directory':
        create_directory(hdfs_client, args.path)
    elif args.command == 'delete_directory':
        delete_directory(hdfs_client, args.path)
    elif args.command == 'create_file':
        create_file(hdfs_client, args.path, args.content)
    elif args.command == 'delete_file':
        delete_file(hdfs_client, args.path)
    elif args.command == 'read_file':
        read_file(hdfs_client, args.path)
    elif args.command == 'list_files':
        list_files(hdfs_client, args.path)
    elif args.command == 'display_metadata':
        display_metadata(hdfs_client, args.path)

if __name__ == "__main__":
    main()
```

To use this script, you need to install the `pywebhdfs` library using pip:

```sh
