2. Implement a CRC generator polynomial and calculate CRCs:

```python
def calculate_crc(data, generator):
    crc = 0
    for byte in data:
        crc ^= byte
        for i in range(8):
            if crc & 0x80:
                crc = (crc << 1) ^ generator
            else:
                crc <<= 1
    return crc
```

3. Generate a CRC-32 checksum for a given string of binary data:

```python
def generate_crc32(data):
    crc = 0xFFFFFFFF
    for byte in data:
        crc ^= byte
        for i in range(8):
            if crc & 0x80000000:
                crc = (crc << 1) ^ 0x04C11DB7
            else:
                crc <<= 1
    return ~crc
```

4. Calculate a CRC-64 checksum for a given string of binary data:

```python
def generate_crc64(data):
    crc = 0xFFFFFFFFFFFFFFFF
    for byte in data:
        crc ^= byte
        for i in range(8):
            if crc & 0x8000000000000000:
                crc = (crc << 1) ^ 0x42F0E1EBA9EA3693
            else:
                crc <<= 1
    return ~crc
```

5. Implement a CRC generator that can handle multiple data blocks and calculate the CRC for each block separately:

```python
def generate_crc(data, generator):
    crc = 0
    for byte in data:
        crc ^= byte
        for i in range(8):
            if crc & 0x80:
                crc = (crc << 1) ^ generator
            else:
                crc <<= 1
    return crc

def generate_crc_blocks(data, generator, block_size):
    crcs = []
    for i in range(0, len(data), block_size):
        block = data[i:i+block_size]
        crcs.append(generate_crc(block, generator))
    return crcs
```

