```python
import datetime

class DateTime:
    def __init__(self, date_str=None, time_str=None, tz_str=None):
        self.date = None
        self.time = None
        self.tz = None

        if date_str:
            self.date = datetime.datetime.strptime(date_str, "%Y-%m-%d")
        if time_str:
            self.time = datetime.datetime.strptime(time_str, "%H:%M:%S").time()
        if tz_str:
            self.tz = datetime.timezone(datetime.timedelta(hours=int(tz_str)))

    def parse(self, date_str, time_str, tz_str=None):
        self.date = datetime.datetime.strptime(date_str, "%Y-%m-%d")
        self.time = datetime.datetime.strptime(time_str, "%H:%M:%S").time()
        if tz_str:
            self.tz = datetime.timezone(datetime.timedelta(hours=int(tz_str)))

    def format(self, format_str):
        if self.tz:
            return self.date.replace(tzinfo=self.tz).strftime(format_str)
        else:
            return self.date.strftime(format_str)

    def convert(self, other):
        if isinstance(other, DateTime):
            if self.tz and other.tz:
                return (self - other).total_seconds() / 3600
            else:
                return (self - other).total_seconds() / 3600
        else:
            raise TypeError("Unsupported type for conversion")

    def __sub__(self, other):
        if isinstance(other, DateTime):
            if self.tz and other.tz:
                return datetime.datetime.combine(self.date, self.time) - datetime.datetime.combine(other.date, other.time)
            else:
                return datetime.datetime.combine(self.date, self.time) - datetime.datetime.combine(other.date, other.time)
        else:
            raise TypeError("Unsupported type for subtraction")
```

This `DateTime` class provides methods for parsing, formatting, and converting dates and times. The `parse` method takes three arguments: `date_str` for the date, `time_str` for the time, and `tz_str` for the time zone. The `format` method takes a `format_str` argument to format the date and time according to the specified format. The `convert` method converts the date and time to a floating-point value representing the number of hours between two `DateTime` instances. Finally, the `__sub__` method performs subtraction between two `DateTime` instances.

Certainly! Here's an example of a Python module that provides a simplified interface for using multiprocessing and multithreading:

```python
import multiprocessing as mp
import threading
import queue

class ProcessManager:
    def __init__(self):
        self.processes = []
        self.process_queue = mp.Queue()
        self.process_queue_lock = mp.Lock()

    def spawn_process(self, target, args=(), kwargs={}):
        p = mp.Process(target=target, args=args, kwargs=kwargs)
        self.processes.append(p)
        p.start()

    def wait_for_processes(self):
        for p in self.processes:
            p.join()

    def send_to_process(self, process_id, data):
        with self.process_queue_lock:
            self.process_queue.put((process_id, data))

    def receive_from_process(self, process_id):
        with self.process_queue_lock:
            while True:
                try:
                    data = self.process_queue.get(block=False)
                    if data[0] == process_id:
                        return data[1]
                except queue.Empty:
                    pass

class ThreadManager:
    def __init__(self):
        self.threads = []
        self.thread_queue = queue.Queue()

    def spawn_thread(self, target, args=(), kwargs={}):
        t = threading.Thread(target=target, args=args, kwargs=kwargs)
        self.threads.append(t)
        t.start()

    def wait_for_threads(self):
        for t in self.threads:
            t.join()

    def send_to_thread(self, thread_id, data):
        self.thread_queue.put((thread_id, data))

    def receive_from_thread(self, thread_id):
        while True:
            try:
                data = self.thread_queue.get(block=False)
                if data[0] == thread_id:
                    return data[1]
            except queue.Empty:
                pass
```

This module provides `ProcessManager` and `ThreadManager` classes to manage processes and threads. The `ProcessManager` class allows you to spawn new processes and synchronize their data, while the `ThreadManager` class allows you to spawn new threads and synchronize their data.

You can use these classes as follows:

```python
# Example usage
if __name__ == '__main__':
    process_manager = ProcessManager()

    # Spawn a new process
    def process_function():
        print("Process function called")

    process_manager.spawn_process(process_function)

    # Send data to the process
    process_manager.send_to_process(0, "Hello from main process")

    # Wait for all processes to finish
    process_manager.wait_for_processes()

    # Example with threads
    thread_manager = ThreadManager()

    # Spawn a new thread
    def thread_function():
        print("Thread function called")

    thread_manager.spawn_thread(thread_function)

    # Send data to the thread
    thread_manager.send_to_thread(0, "Hello from main thread")

    # Wait for all threads to finish
    thread_manager.wait_for_threads()
```

You can modify the `ProcessManager` and `ThreadManager` classes to suit your specific needs and requirements.

