Here is a Python code that implements a self-service finite-state machine for an ATM system, allowing users to withdraw cash, check their balance, and change their PIN using a menu-driven interface:

```python
class ATM:
    def __init__(self, balance=0, pin="1234"):
        self.balance = balance
        self.pin = pin
        self.state = "login"

    def login(self):
        while self.state == "login":
            print("Welcome to the ATM!")
            print("Please enter your PIN:")
            user_pin = input()
            if user_pin == self.pin:
                print("PIN accepted. Please choose an option:")
                self.state = "options"
            else:
                print("Invalid PIN. Please try again.")

    def options(self):
        while self.state == "options":
            print("1. Withdraw cash")
            print("2. Check balance")
            print("3. Change PIN")
            print("4. Exit")
            user_choice = input()
            if user_choice == "1":
                self.withdraw()
            elif user_choice == "2":
                self.check_balance()
            elif user_choice == "3":
                self.change_pin()
            elif user_choice == "4":
                print("Thank you for using the ATM. Goodbye!")
                self.state = "logout"
            else:
                print("Invalid choice. Please try again.")

    def withdraw(self):
        while self.state == "withdraw":
            print("Please enter the amount you would like to withdraw:")
            amount = float(input())
            if amount <= self.balance:
                self.balance -= amount
                print("Withdrawal successful. Your new balance is:", self.balance)
                self.state = "options"
            else:
                print("Insufficient funds. Please try again.")

    def check_balance(self):
        while self.state == "check_balance":
            print("Your current balance is:", self.balance)
            self.state = "options"

    def change_pin(self):
        while self.state == "change_pin":
            print("Please enter your current PIN:")
            user_pin = input()
            if user_pin == self.pin:
                print("PIN accepted. Please enter your new PIN:")
                new_pin = input()
                print("PIN changed successfully. Please re-enter your new PIN:")
                confirm_pin = input()
                if confirm_pin == new_pin:
                    self.pin = new_pin
                    print("PIN changed successfully. Please log in again.")
                    self.state = "login"
                else:
                    print("PIN confirmation failed. Please try again.")
            else:
                print("Invalid PIN. Please try again.")


atm = ATM()
atm.login()
```

