Here's an implementation of an appendable key-value storage system using a binary search tree (BST) in Python. This system allows for efficient insertion, deletion, and retrieval of values by key.

```python
class Node:
    def __init__(self, key, value):
        self.key = key
        self.value = value
        self.left = None
        self.right = None

class AppendableKeyValStorage:
    def __init__(self):
        self.root = None

    def insert(self, key, value):
        if self.root is None:
            self.root = Node(key, value)
        else:
            self._insert(self.root, key, value)

    def _insert(self, node, key, value):
        if key < node.key:
            if node.left is None:
                node.left = Node(key, value)
            else:
                self._insert(node.left, key, value)
        elif key > node.key:
            if node.right is None:
                node.right = Node(key, value)
            else:
                self._insert(node.right, key, value)
        else:
            node.value = value

    def delete(self, key):
        if self.root is None:
            return
        else:
            self._delete(self.root, key)

    def _delete(self, node, key):
        if key < node.key:
            if node.left is not None:
                self._delete(node.left, key)
        elif key > node.key:
            if node.right is not None:
                self._delete(node.right, key)
        else:
            if node.left is None and node.right is None:
                node = None
            elif node.left is None:
                node = node.right
            elif node.right is None:
                node = node.left
            else:
                min_node = self._find_min(node.right)
                node.key = min_node.key
                node.value = min_node.value
                self._delete(node.right, min_node.key)

    def _find_min(self, node):
        while node.left is not None:
            node = node.left
        return node

    def retrieve(self, key):
        if self.root is None:
            return None
        else:
            return self._retrieve(self.root, key)

    def _retrieve(self, node, key):
        if key < node.key:
            if node.left is not None:
                return self._retrieve(node.left, key)
            else:
                return None
        elif key > node.key:
            if node.right is not None:
                return self._retrieve(node.right, key)
            else:
                return None
        else:
            return node.value
```

This implementation uses a Node class to represent each node in the BST, and an AppendableKeyValStorage class to manage the storage system. The insert method inserts a key-value pair into the BST, the delete method deletes a key-value pair from the BST, and the retrieve method retrieves a value by key. The code is designed to be efficient in terms of time complexity for insertion, deletion, and retrieval operations.

