Here's an example of how you can use the `yaml` module to parse YAML files and raise an error if any syntax errors are found, and also check for valid indentation and proper keys in the YAML files using a set of defined rules:

```python
import yaml

def validate_yaml_file(file_path):
    try:
        with open(file_path, 'r') as file:
            yaml_content = yaml.safe_load(file)
            if yaml_content is None:
                raise ValueError("Invalid YAML file format")

            # Check for valid indentation
            for key, value in yaml_content.items():
                if isinstance(value, dict):
                    for sub_key, sub_value in value.items():
                        if isinstance(sub_value, dict):
                            for sub_sub_key, sub_sub_value in sub_value.items():
                                if not isinstance(sub_sub_value, (str, int, float)):
                                    raise ValueError(f"Invalid value for key '{sub_sub_key}' in file '{file_path}'")

            # Check for valid keys
            valid_keys = {"name", "age", "address"}
            for key in yaml_content.keys():
                if key not in valid_keys:
                    raise ValueError(f"Invalid key '{key}' in file '{file_path}'")

            print(f"YAML file '{file_path}' is valid")
    except yaml.YAMLError as e:
        raise ValueError(f"Error parsing YAML file '{file_path}': {e}")
    except ValueError as e:
        raise ValueError(f"Invalid YAML file '{file_path}': {e}")

# Example usage
try:
    validate_yaml_file('example.yaml')
except ValueError as e:
    print(e)
```

This code defines a function `validate_yaml_file` that takes a file path as input and tries to parse the YAML file using the `yaml.safe_load` function. It checks for valid indentation and proper keys in the YAML file and raises an error if any issues are found. If the YAML file is valid, it prints a success message.

