                'DomainName': 'my-origin-domain-name',
                'OriginPath': '/',
                'CustomHeaders': {
                    'Quantity': 0,
                    'Items': []
                },
                'OriginSSLProtocols': {
                    'Quantity': 1,
                    'Items': [
                        'TLSv1.2'
                    ]
                },
                'HTTPPort': 80,
                'HTTPSPort': 443,
                'OriginProtocolPolicy': 'https-only'
            }
        ]
    },
    'DefaultCacheBehavior': {
        'TargetOriginId': 'my-origin-id',
        'ForwardedValues': {
            'QueryString': False,
            'Cookies': {
                'Forward': 'none'
            },
            'Headers': {
                'Quantity': 0,
                'Items': []
            }
        },
        'TrustedSigners': {
            'Enabled': False,
            'Quantity': 0,
            'Items': []
        },
        'ViewerProtocolPolicy': 'allow-all',
        'MinTTL': 0,
        'AllowedMethods': {
            'Quantity': 2,
            'Items': [
                'GET',
                'HEAD'
            ],
            'CachedMethods': {
                'Quantity': 2,
                'Items': [
                    'GET',
                    'HEAD'
                ]
            }
        },
        'DefaultTTL': 86400,
        'MaxTTL': 31536000
    },
    'Comment': 'My CloudFront distribution',
    'Enabled': True
}
response = cloudfront.create_distribution(DistributionConfig=distribution_config)
distribution_id = response['Distribution']['Id']

# List all CloudFront distributions
